"""Generated, minified and compiled files are recognised by their content."""

import pytest

from scheduler.acceptance.generated import exclusion_reason, header_comment

GENERATED = {
    "swig.cpp": "/* ---\n * This file was automatically generated by SWIG (https://www.swig.org).\n * Version 4.1.1\n */\n#include <x>\n",
    "message_pb2.py": "# -*- coding: utf-8 -*-\n# Generated by the protocol buffer compiler.  DO NOT EDIT!\n# source: a.proto\n\"\"\"Generated protocol buffer code.\"\"\"\nfrom google.protobuf import descriptor\n",
    "Message.java": "// Generated by the protocol buffer compiler.  DO NOT EDIT!\n// source: a.proto\n\npackage a;\n",
    "Form.Designer.cs": "//------------------------------------------------------------------------------\n// <auto-generated>\n//     This code was generated by a tool.\n// </auto-generated>\n//------------------------------------------------------------------------------\nnamespace A {}\n",
    "bindings.rs": "/* automatically generated by rust-bindgen 0.69.4 */\n\npub const A: u32 = 1;\n",
    "prost.rs": "// This file is @generated by prost-build.\npub struct A {}\n",
    "api.pb.go": "// Code generated by protoc-gen-go. DO NOT EDIT.\n// versions:\n\npackage api\n",
    "module.c": "/* Generated by Cython 3.0.11 */\n\n#define PY_SSIZE_T_CLEAN\n",
    "HelloParser.java": "// Generated from Hello.g4 by ANTLR 4.13.1\npackage a;\n",
    "moc_window.cpp": "/****************************************************************************\n** Meta object code from reading C++ file 'window.h'\n**\n** Created by: The Qt Meta Object Compiler version 68 (Qt 6.5.0)\n**\n** WARNING! All changes made in this file will be lost!\n*****************************************************************************/\n\n#include \"window.h\"\n",
    "Jni.h": "/* DO NOT EDIT THIS FILE - it is machine generated */\n#include <jni.h>\n",
    "0001_initial.py": "# Generated by Django 4.2 on 2024-01-01 12:00\n\nfrom django.db import migrations\n",
    "Licensed.java": "/*\n * Copyright 2024 Example\n *\n * Licensed under the Apache License, Version 2.0.\n */\n\n// Generated by jOOQ\npackage a;\n",
    "Api.ts": "/* tslint:disable */\n/* eslint-disable */\n/**\n * Petstore\n * NOTE: This class is auto generated by OpenAPI Generator (https://openapi-generator.tech).\n * Do not edit the class manually.\n */\nexport class Api {}\n",
}

OWN_CODE = {
    # A code generator's own source writes the marker as a string: code, not a comment.
    "gen.py": '"""Writes the protobuf stubs."""\nHEADER = "# Generated by the protocol buffer compiler.  DO NOT EDIT!"\n',
    "Gen.java": "package gen;\n\n// DO NOT EDIT below this line\nclass Gen {}\n",
    "reports.py": '"""Reads the reports generated by PMD and Ruff."""\nimport json\n',
    "header.h": "#ifndef A_H\n#define A_H\n/* Code generated by hand */\n#endif\n",
    "Annotated.java": "package a;\n\nimport javax.annotation.processing.Generated;\n\n@Generated(\"x\")\nclass Annotated {}\n",
    "app.js": "// Entry point\nexport function main() {\n  return 1;\n}\n",
    "types.d.ts": "export interface Api {}\n",
    "app.ts": "export const a = 1;\n",
}


@pytest.mark.parametrize("name", sorted(GENERATED))
def test_generator_markers_in_the_header_comment(tmp_path, name):
    path = tmp_path / name
    path.write_text(GENERATED[name])
    assert (exclusion_reason(path) or "").startswith("generated: ")


@pytest.mark.parametrize("name", sorted(OWN_CODE))
def test_own_code_is_not_excluded(tmp_path, name):
    path = tmp_path / name
    path.write_text(OWN_CODE[name])
    assert exclusion_reason(path) is None


def test_reason_names_the_marker_line(tmp_path):
    path = tmp_path / "a.java"
    path.write_text(GENERATED["Message.java"])
    assert exclusion_reason(path) == "generated: Generated by the protocol buffer compiler.  DO NOT EDIT!"


def test_minified_javascript(tmp_path):
    path = tmp_path / "bundle.js"
    path.write_text("/*! lib v1 */\n" + "var a=1;" * 500 + "\n")
    assert exclusion_reason(path).startswith("minified: average line length")


def test_compiled_javascript_with_source_map(tmp_path):
    path = tmp_path / "index.js"
    path.write_text('"use strict";\nexports.a = 1;\n//# sourceMappingURL=index.js.map\n')
    assert exclusion_reason(path) == "compiled: source map comment"


@pytest.mark.parametrize(
    ("name", "content"),
    [("tiles.tsx", '<?xml version="1.0"?>\n<tileset/>\n'), ("app_de.ts", "<!DOCTYPE TS>\n<TS/>\n")],
)
def test_xml_with_typescript_extension(tmp_path, name, content):
    path = tmp_path / name
    path.write_text(content)
    assert exclusion_reason(path) == "XML, not TypeScript"


def test_header_comment_stops_at_the_first_line_of_code():
    lines = ["#!/usr/bin/env python", "# a", "", '"""doc', 'string"""', "import os", "# later"]
    assert header_comment(lines) == ["#!/usr/bin/env python", "# a", '"""doc', 'string"""']
    assert header_comment(["#include <a.h>", "// generated"]) == []


def test_missing_file(tmp_path):
    assert exclusion_reason(tmp_path / "missing.py") is None
